def merge(base, override):
    """Merge two settings dicts. Nested dicts are merged key by key."""
    return {**base, **override}

from config import merge


def test_override_wins():
    assert merge({'a': 1}, {'a': 2}) == {'a': 2}


def test_nested_keys_kept():
    base = {'db': {'host': 'a', 'port': 5432}}
    assert merge(base, {'db': {'host': 'b'}}) == {'db': {'host': 'b', 'port': 5432}}


def test_inputs_unchanged():
    base = {'db': {'host': 'a'}}
    merge(base, {'db': {'host': 'b'}})
    assert base == {'db': {'host': 'a'}}

